<script setup>
import{ref,reactive,computed,onMounted}from'vue';
import{requestApi}from'../../shared/infrastructure/http/apiClient.js';
import{submitOperation,pendingOperations,retryOperation}from'../../shared/infrastructure/http/pendingOperation.js';
const props=defineProps({identity:Object,online:Boolean});
const materials=ref([]),products=ref([]),error=ref(''),notice=ref(''),busy=ref(false),pending=ref([]),search=ref(''),category=ref('');
const lotId=ref(''),qrValue=ref(''),external=reactive({mineralType:'Gold',weight:'',weightUnit:'g',source:''}),name=ref(''),reason=ref(''),editing=ref(null),composition=ref([{materialId:'',weight:'',weightUnit:'g'}]);
const labels={Documented:'Documentado',Declared:'Declarado · pendiente de revisión',External:'Externo · sin verificar'};
const scope=()=>({tenantId:props.identity.tenantId,userId:props.identity.userId,resourceId:'inventory'});
const visible=computed(()=>materials.value.filter(m=>(!category.value||m.category===category.value)&&`${m.id} ${m.lotId??''} ${m.mineralType} ${m.source}`.toLowerCase().includes(search.value.toLowerCase())));
async function load(){try{materials.value=(await requestApi('/api/v1/jewelry/inventory')).materials;products.value=(await requestApi('/api/v1/jewelry/products')).products;pending.value=pendingOperations(scope());}catch(e){error.value=e.message;}}
onMounted(load);
async function act(action,path,payload,method='POST'){
 busy.value=true;error.value='';notice.value='';try{const result=await submitOperation(path,payload,scope(),action,method);notice.value=`Operación de inventario confirmada.${result.productId?' Joya: '+result.productId:''}`;await load();return result;}catch(e){error.value=e.message;pending.value=pendingOperations(scope());}finally{busy.value=false;}
}
async function receipt(){try{let qrLotId=qrValue.value.trim();if(qrLotId.includes('/')){const url=new URL(qrLotId,window.location.origin);if(url.origin!==window.location.origin||!/^\/lots\/[0-9a-f-]+\/?$/i.test(url.pathname))throw Error('El código QR no contiene un enlace de lote de EventOre');qrLotId=url.pathname.split('/')[2];}const lot=await requestApi(`/api/v1/lots/${lotId.value.trim()}`);await act('receipt','/api/v1/jewelry/lots/'+lot.lotId+'/receipt',{expectedVersion:lot.version,qrLotId});}catch(e){error.value=e.message;}}
async function save(){const result=await act('composition',editing.value?`/api/v1/jewelry/products/${editing.value.id}/composition`:'/api/v1/jewelry/products',{name:name.value,reason:reason.value,allocations:composition.value.map(a=>({...a})),...(editing.value?{expectedVersion:editing.value.version}:{})},editing.value?'PUT':'POST');if(result){editing.value=null;name.value='';reason.value='';composition.value=[{materialId:'',weight:'',weightUnit:'g'}];}}
async function edit(id){try{const p=await requestApi(`/api/v1/jewelry/products/${id}`);editing.value=p;name.value=p.name;reason.value='';composition.value=p.composition.map(m=>({materialId:m.materialId,weight:m.quantityGrams,weightUnit:'g'}));}catch(e){error.value=e.message;}}
async function retry(attempt){busy.value=true;try{await retryOperation(attempt);await load();notice.value='Reintento confirmado.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template>
<section class="panel" aria-label="Inventario de joyería"><h2>Inventario de joyería</h2><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert" role="status">{{notice}}</p>
 <p v-for="attempt in pending" :key="attempt.key" class="alert">Operación sin confirmar. <button :disabled="busy||!online" @click="retry(attempt)">Reintentar inventario</button></p>
 <div class="columns"><form @submit.prevent="receipt"><h3>Recibir lote procesado</h3><label>ID del lote recibido por QR<input v-model="lotId" required /></label><label>Contenido del QR de recepción<input v-model="qrValue" required placeholder="Enlace del lote o UUID leído" /></label><button :disabled="busy||!online">Recibir en joyería</button><p class="muted">La recepción conserva la revisión real del origen. Un QR no convierte una declaración en evidencia verificada.</p></form>
 <form @submit.prevent="act('external','/api/v1/jewelry/external-materials',{...external})"><h3>Declarar material externo</h3><label>Mineral externo<input v-model="external.mineralType" required /></label><label>Cantidad externa<input v-model="external.weight" required inputmode="decimal" /></label><label>Unidad externa<select v-model="external.weightUnit"><option>g</option><option>kg</option><option>t</option></select></label><label>Fuente declarada del material externo<input v-model="external.source" required /></label><button :disabled="busy||!online">Guardar material externo</button></form></div>
 <div class="formrow"><label>Buscar material<input v-model="search" placeholder="ID, lote, mineral o fuente" /></label><label>Categoría de inventario<select v-model="category"><option value="">Todas</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label></div>
 <div class="table-scroll"><table><thead><tr><th>Material</th><th>Procedencia y revisión</th><th>Disponible</th></tr></thead><tbody><tr v-for="material in visible" :key="material.id"><td><strong>{{material.mineralType}}</strong><p class="identifier">{{material.id}}</p><small v-if="material.lotId">Lote {{material.lotId}}</small></td><td>{{labels[material.category]}}<p>{{material.source}}</p></td><td>{{material.availableGrams}} g de {{material.quantityGrams}} g</td></tr></tbody></table></div><p v-if="!visible.length">No hay materiales que coincidan.</p>
 <form @submit.prevent="save"><h3>{{editing?'Corregir composición':'Crear joya y asignar materiales'}}</h3><label>Nombre de joya<input v-model="name" required maxlength="200" /></label>
 <fieldset v-for="(item,index) in composition" :key="index"><legend>Material {{index+1}}</legend><label>Material de composición<select v-model="item.materialId" required><option value="">Selecciona material</option><option v-for="m in materials" :key="m.id" :value="m.id">{{m.id}} · {{labels[m.category]}} · {{m.availableGrams}} g</option></select></label><div class="formrow"><label>Cantidad asignada<input v-model="item.weight" required inputmode="decimal" /></label><label>Unidad de asignación<select v-model="item.weightUnit"><option>g</option><option>kg</option><option>t</option></select></label></div><button v-if="composition.length>1" type="button" class="secondary" @click="composition.splice(index,1)">Quitar material</button></fieldset>
 <button type="button" class="secondary" :disabled="composition.length>=20" @click="composition.push({materialId:'',weight:'',weightUnit:'g'})">Agregar material</button><label>Motivo de composición<input v-model="reason" required /></label><p class="muted">El material externo se mantiene separado. Toda corrección conserva el historial y obliga a revisar los certificados afectados.</p><button :disabled="busy||!online">{{editing?'Guardar corrección de composición':'Crear joya'}}</button><button v-if="editing" type="button" class="secondary" @click="editing=null;name='';reason='';composition=[{materialId:'',weight:'',weightUnit:'g'}]">Cancelar edición</button>
 </form>
 <h3>Joyas registradas</h3><ul class="history-list"><li v-for="product in products" :key="product.id"><strong>{{product.name}} · versión {{product.version}}</strong><p class="identifier">{{product.id}}</p><button class="secondary" @click="edit(product.id)">Ver composición y corregir</button></li></ul>
 <details v-if="editing"><summary>Historial de composición</summary><ol><li v-for="event in editing.history" :key="event.version">Versión {{event.version}} · {{event.reason}}<p>Antes: {{event.beforeComposition.map(m=>m.materialId+': '+m.quantityGrams+' g').join(', ')||'Sin asignación'}}</p><p>Después: {{event.afterComposition.map(m=>m.materialId+': '+m.quantityGrams+' g').join(', ')}}</p></li></ol></details>
</section>
</template>
